// память O(min(n, k)): в окне только последние k чисел
var window = new HashSet<int>();
for (int i = 0; i < nums.Length; i++) {
    if (!window.Add(nums[i])) return true;              // такое же число в окне
    if (window.Count > k) window.Remove(nums[i - k]);   // самое старое — вон
}
return false;

